// LED rojo con halo y punto blanco
const Led: React.FC<{x: number; y: number; r?: number; a?: number; c?: string; ph?: number}> = ({x, y, r = 14, a = 1, c = RED, ph = 0}) => {
  const {s} = useS();
  const p = 0.78 + 0.22 * Math.sin(s * 3.2 + ph);
  if (a <= 0.01) return null;
  return (
    <g opacity={a}>
      <circle cx={x} cy={y} r={r * 5.5 * p} fill={c} opacity={0.1} />
      <circle cx={x} cy={y} r={r * 3 * p} fill={c} opacity={0.22} />
      <circle cx={x} cy={y} r={r * 1.7} fill={c} opacity={0.5} />
      <circle cx={x} cy={y} r={r} fill="#ff8a8a" stroke={c} strokeWidth={2} />
      <circle cx={x - r * 0.3} cy={y - r * 0.3} r={r * 0.35} fill="#fff" opacity={0.9} />
    </g>
  );
};

// cartera de cuero; abre 0..1 (la solapa baja), lleno 0..1 (billetes que asoman)
const CarteraAb: React.FC<{x: number; y: number; k?: number; abre: number; lleno: number; c1?: string; c2?: string}> = ({x, y, k = 1, abre, lleno, c1 = '#58b068', c2 = '#6fc27a'}) => {
  const n = Math.round(lleno * 5);
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <defs><linearGradient id="cueroW" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient></defs>
      <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
      {n > 0 && Array.from({length: n}).map((_, i) => (
        <rect key={i} x={-130 + i * 52} y={-150 - lleno * 70 - (i % 2) * 18} width={92} height={140} rx={6} fill={i % 2 ? c2 : c1} stroke="rgba(0,0,0,0.4)" strokeWidth={3} transform={`rotate(${(i - 2) * 5} ${-84 + i * 52} -20)`} />
      ))}
      <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cueroW)" stroke="#2c180a" strokeWidth={5} />
      {abre > 0.03 && <rect x={-170} y={-110} width={340} height={100 + 130 * abre} rx={14} fill="#241206" opacity={0.9} />}
      <g transform={`translate(0 ${abre * 175}) scale(1 ${1 - abre * 0.55})`}>
        <rect x={-190} y={-40} width={380} height={170} rx={26} fill="url(#cueroW)" stroke="#2c180a" strokeWidth={5} />
        <rect x={-170} y={-22} width={340} height={134} rx={16} fill="none" stroke="#c9a074" strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
        <rect x={120} y={10} width={70} height={64} rx={14} fill={GOLD} stroke="#2c180a" strokeWidth={4} />
      </g>
      <path d="M -190 -60 Q 0 -30 190 -60 L 190 -90 Q 0 -120 -190 -90 Z" fill="rgba(255,255,255,0.10)" />
    </g>
  );
};

const Corte: React.FC<{t: number; antes: React.ReactNode; despues: React.ReactNode}> = ({t, antes, despues}) => {
  const {s} = useS();
  return <AbsoluteFill>{s < t ? antes : despues}</AbsoluteFill>;
};

