const BANCOS = en('bancos'), APPS = en('apps'), ESTAFA = en('estafa'), ALGUIEN = en('alguien'), MANDO = en('mando'), DEVUELVAS2 = en('devuelvas', 2), DILE = en('dile'), BANCO2 = en('banco', 2), AVISA = en('avisa'), TUYO = en('tuyo');
const DALE = en('dale'), ERROR3 = en('error', 3), ENVIASELO = en('enviaselo');

// punta del dedo indice -> donde poner la mano (k = escala, r = giro en grados)
const tipAt = (tx: number, ty: number, r = 0, k = 0.7) => {
  const a = (r * Math.PI) / 180, d = 220 * k;
  return {x: tx - d * Math.sin(a), y: ty + d * Math.cos(a)};
};
const SOMBRA = 'rgba(0,0,0,0.4)';

