  const b = spr(t, 10, 150);
  if (b <= 0.01) return null;
  return (
    <g transform={`translate(0 ${y - (1 - b) * 260}) scale(${0.9 + 0.1 * b})`} opacity={Math.min(1, b * 1.4)}>
      <rect x={-188} y={-62} width={376} height={124} rx={28} fill={SOMBRA} transform="translate(4 8)" />
      <rect x={-188} y={-62} width={376} height={124} rx={28} fill={color} stroke="rgba(0,0,0,0.3)" strokeWidth={3} />
