      <text x={-136} y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={42} fill="#fff">{icono}</text>
      <text x={-86} y={-12} fontFamily={FONT} fontWeight={800} fontSize={24} fill="rgba(0,0,0,0.6)">{titulo}</text>
      <text x={-86} y={32} fontFamily={FONT} fontWeight={800} fontSize={tam} fill="#2a2208">{texto}</text>
    </g>
  );
};

