        <g key={i} opacity={0.9 - i * 0.2}>
          <rect x={-188} y={20 + i * 82} width={376} height={62} rx={16} fill="rgba(255,255,255,0.07)" />
          <circle cx={-150} cy={51 + i * 82} r={18} fill="rgba(255,255,255,0.14)" />
          <rect x={-114} y={42 + i * 82} width={150 + h(i + 80) * 60} height={14} rx={7} fill="rgba(255,255,255,0.2)" />
          <rect x={90} y={44 + i * 82} width={80} height={14} rx={7} fill="rgba(255,255,255,0.14)" />
        </g>
      ))}
      {lista && (
        <g transform={`translate(0 ${330}) scale(${press})`}>
          <rect x={-170} y={-42} width={340} height={84} rx={42} fill={BLUE} stroke="rgba(255,255,255,0.35)" strokeWidth={3} />
          <text x={0} y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={38} fill="#fff">DEVOLVER</text>
          <path d={`M -150 -30 Q 0 ${-44 + Math.sin(s * 3) * 2} 150 -30`} stroke="rgba(255,255,255,0.3)" strokeWidth={4} fill="none" strokeLinecap="round" />
        </g>
      )}
    </g>
  );
};

// chat con el desconocido. fijo: todas las burbujas ya puestas. extra: 0..1 empuja una burbuja mas
const MSGS: {t: number; txt: string; w: number; casa?: boolean}[] = [
  {t: PERDON, txt: 'Perdón', w: 200},
  {t: EQUIV, txt: 'Me equivoqué de número', w: 372},
  {t: PUEDES, txt: '¿Me lo puedes devolver?', w: 372},
  {t: RENTA, txt: 'Es para la renta', w: 300, casa: true},
];
const ChatPant: React.FC<{fijo?: boolean; extra?: number; enviar?: number; press?: number}> = ({fijo = false, extra = 0, enviar, press = 0}) => {
  const {s, spr} = useS();
  const app = (i: number) => (fijo ? 1 : eo(ro(s, MSGS[i].t - 0.05, MSGS[i].t + 0.3)));
  return (
    <g>
      <BarraEstado />
      <circle cx={-150} cy={-366} r={30} fill="#5b6786" />
      <text x={-150} y={-354} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={36} fill="#fff">?</text>
      <text x={-100} y={-362} fontFamily={FONT} fontWeight={800} fontSize={28} fill="#fff">Desconocido</text>
      <text x={-100} y={-338} fontFamily={FONT} fontWeight={800} fontSize={18} fill="#7e8cb0">+1 809 ··· ····</text>
      <rect x={-212} y={-320} width={424} height={3} fill="rgba(255,255,255,0.1)" />
      {MSGS.map((m, i) => {
        let up = 0;
        for (let j = i + 1; j < MSGS.length; j++) up += 92 * app(j);
        const a = fijo ? 1 : spr(m.t - 0.05, 12, 170);
        if (a <= 0.01) return null;
        const y = 215 - up - extra * 92;
        return (
          <g key={i} transform={`translate(0 ${y}) scale(${Math.min(1, a)})`} opacity={Math.min(1, a * 1.5)}>
            <rect x={-188} y={-35} width={m.w} height={70} rx={26} fill="#e9edf5" />
            <path d="M -188 20 L -208 40 L -170 34 Z" fill="#e9edf5" />
            <text x={-188 + (m.casa ? 112 : m.w / 2)} y={9} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={26} fill="#1b2438">{m.txt}</text>
            {m.casa && (
              <g transform="translate(160 0)">
                <circle r={32} fill={GOLD} stroke="rgba(0,0,0,0.3)" strokeWidth={3} />
                <polygon points="-20,-4 0,-22 20,-4" fill="#6a3a14" />
                <rect x={-14} y={-4} width={28} height={22} fill="#fff3d6" stroke="#6a3a14" strokeWidth={3} />
                <rect x={-5} y={5} width={10} height={13} fill="#6a3a14" />
              </g>
            )}
          </g>
        );
      })}
      {!fijo && (
        <g transform="translate(0 305)">
          <rect x={-188} y={-26} width={130} height={56} rx={26} fill="#e9edf5" opacity={0.85} />
          {[0, 1, 2].map((i) => <circle key={i} cx={-150 + i * 34} cy={Math.sin(s * 8 + i * 1.2) * 7 + 2} r={9} fill="#6b7694" />)}
        </g>
      )}
      {enviar !== undefined && (
        <g>
          <g opacity={ro(s, enviar, enviar + 0.2)} transform={`translate(0 ${215 - 0 * 92 + (1 - eo(ro(s, enviar, enviar + 0.3))) * 90})`}>
            <rect x={-60} y={-35} width={248} height={70} rx={26} fill={BLUE} />
            <text x={64} y={10} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={30} fill="#fff">Enviado $200</text>
          </g>
          <rect x={-190} y={368} width={296} height={62} rx={31} fill="rgba(255,255,255,0.1)" />
          <text x={-168} y={408} fontFamily={FONT} fontWeight={800} fontSize={26} fill="#9fb0d8">Devolver $200</text>
          <g transform={`translate(150 399) scale(${1 - 0.22 * press})`}>
            <circle r={34} fill={BLUE} stroke="rgba(255,255,255,0.4)" strokeWidth={3} />
            <path d="M 0 -16 L 0 14 M -14 -2 L 0 -16 L 14 -2" stroke="#fff" strokeWidth={6} fill="none" strokeLinecap="round" strokeLinejoin="round" />
          </g>
        </g>
      )}
    </g>
  );
};

// banco con columnas
